from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            upper = grid[:r]
            lower = grid[r + 1:]
            upper_color = Counter(x for line in upper for x in line).most_common(1)[0][0]
            lower_bg = Counter(x for line in lower for x in line).most_common(1)[0][0]
            return [
                [3 if lower[i][j] != lower_bg else upper_color
                 for j in range(w)]
                for i in range(len(upper))
            ]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            upper_color = Counter(x for line in left for x in line).most_common(1)[0][0]
            lower_bg = Counter(x for line in right for x in line).most_common(1)[0][0]
            return [
                [3 if right[i][j] != lower_bg else upper_color
                 for j in range(c)]
                for i in range(h)
            ]

    return grid
